{
  "headline": "FDA's records trace our supply to a plant classified OAI 510 days before the posting",
  "headline_cites": ["D8"],
  "sentences": [
    {
      "text": "FDA first posted the hydromorphone hydrochloride injection shortage on 2017-10-31 and it remains Current as of 2026-10-21.",
      "cites": ["E38", "E33", "E34", "E35", "E36"]
    },
    {
      "text": "The shortage posting lists Fresenius Kabi USA LLC, Hikma Pharmaceuticals USA Inc., Hospira Inc. (a Pfizer Company), and Teva Pharmaceuticals USA Inc. as affected manufacturers.",
      "cites": ["E33", "E34", "E35", "E36"]
    },
    {
      "text": "Our Corvale East and Corvale General sites both use the Hikma Pharmaceuticals USA Inc. 2 mg/mL 20 mL vial (NDC 00641234141).",
      "cites": ["E2", "E5"]
    },
    {
      "text": "FDA inspection 976095 of Hospira Inc. (FEI 1925262) ended 2016-06-08 with an OAI classification, 510 days before the shortage posting.",
      "cites": ["D8", "E24"]
    },
    {
      "text": "A Warning Letter was issued to Hospira Inc. (FEI 1925262) on 2017-02-14, 259 days before the posting.",
      "cites": ["D9", "E29"]
    },
    {
      "text": "FDA inspection 1031233 of Hospira Inc. (FEI 1925262) ended 2017-10-27 with a VAI classification, 4 days before the posting.",
      "cites": ["D10", "E25"]
    },
    {
      "text": "The highest-ranked mitigation is to transfer 139 vials of the 2 mg/mL 20 mL presentation from Corvale General (21.3 days on hand) to Corvale East (2.8 days on hand), which would leave Corvale General with 14 days and bring Corvale East to 9 days.",
      "cites": ["D1", "D2", "D15"]
    }
  ]
}
